const listEligiblePeople = `-- name: ListEligiblePeople :many
SELECT p.id, p.first_name, p.last_name
FROM people p
JOIN open_day_staff_requirements r ON r.id = $1
WHERE EXISTS (
      SELECT 1 FROM person_roles mp JOIN roles m ON m.id = mp.role_id
      WHERE mp.person_id = p.id AND m.system_key = r.kind
  )
  AND (
      NOT EXISTS (SELECT 1 FROM open_day_staff_requirement_roles rr WHERE rr.requirement_id = r.id)
      OR EXISTS (
          SELECT 1 FROM open_day_staff_requirement_roles rr
          JOIN person_roles pr ON pr.role_id = rr.role_id
          WHERE rr.requirement_id = r.id AND pr.person_id = p.id
      )
  )
  AND ($2::text = '' OR lower(p.first_name || ' ' || p.last_name) LIKE '%' || lower($2::text) || '%')
ORDER BY p.last_name, p.first_name, p.id
LIMIT $3
`

type ListEligiblePeopleParams struct {
	RequirementID uuid.UUID
	Search        string
	PageLimit     int32
}

type ListEligiblePeopleRow struct {
	ID        uuid.UUID
	FirstName string
	LastName  string
}

